 await p.route('**/game.js',async route=>{const r=await route.fetch();let src=await r.text();src=ending==='VICTORY'?src.replace(needle,'const enemyHQ = false'):src.replace(needle,'const ownHQ = false');await route.fulfill({response:r,body:src});});
 await p.goto('http://localhost:3000');await p.locator('#start-btn').click();await p.waitForFunction(()=>!document.querySelector('#end-screen').classList.contains('hidden'),{timeout:5000});console.log(JSON.stringify({expected:ending,actual:await p.locator('#end-title').textContent(),endClass:await p.locator('#end-screen').getAttribute('class'),errors}));await p.close();
}
await b.close();
